# Generated by Codebuff for request: make the Hectic Lab AI agent respond as fast
# as possible without breaking existing behaviour or introducing another vector DB.
#
# Removed:
#   - GEMINI_EMBEDDING_MODEL, GEMINI_CHAT_MODEL, CHAT_RETRIEVAL_LIMIT,
#     CHAT_DISTANCE_THRESHOLD, CHROMA_PERSIST_DIRECTORY
#   - All chromadb / vector / knowledge-index configuration
# Added:
#   - AI_CHAT_CACHE_ENABLED / AI_CHAT_CACHE_TTL_SECONDS for repeated-question
#     answer caching (no new dependency; uses the existing Django cache backend)
#   - CACHES so a Redis URL (if configured) is used; otherwise the DB cache.
#   - Default GEMINI_CHAT_MODEL pointing at a gated, low-thinking-overhead
#     Flash model. The app selects the fastest registered model at runtime.

"""
Django settings for portfolio project.
"""

from datetime import timedelta
from pathlib import Path

try:
    from decouple import Csv, config
except ImportError:
    import os
    try:
        from dotenv import load_dotenv
        _env_file = Path(__file__).resolve().parent.parent.parent / ".env"
        if _env_file.exists():
            load_dotenv(_env_file)
    except ImportError:
        pass

    def config(key, default="", cast=None):
        val = os.getenv(key)
        if val is None or val == "":
            val = default
        if cast is bool:
            return str(val).strip().lower() in ("true", "1", "t", "yes", "y")
        if cast is int:
            return int(val) if val is not None and str(val).strip() != "" else (default if default is not None else 0)
        if callable(cast):
            return cast(val)
        return val

    class Csv:
        def __call__(self, val):
            if isinstance(val, (list, tuple)):
                return val
            if not val:
                return []
            return [x.strip() for x in str(val).split(",") if x.strip()]


